import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  canonicalize, checkChains, parseCanonicalSource, parseSource, SourceError,
} from "../src/core/source.js";
import {
  abiDecode, cst, defineSource, evmCall, formatValue, gt, httpInput, jsonDecode, jsonPriceSource, layoutDecode, lintSource, num,
  ref, rescale, svmAccount, verifyPreimage,
} from "../src/core/sourcebuild.js";

// source-vectors.json is generated by the node client (`go test ./new/source -run TestVectors -update`)
// and shared by every implementation of the source format.
interface Vectors {
  canonical: { name: string; input: string; canonical: string; sourceId: string }[];
  reject: { name: string; input: string; inputHex?: string; class: string }[];
  escaping: { input: string; want: string }[];
}
const vectors: Vectors = JSON.parse(readFileSync(new URL("./source-vectors.json", import.meta.url), "utf8"));
const hexToBytes = (h: string): Uint8Array => Uint8Array.from(h.match(/../g) ?? [], (b) => parseInt(b, 16));
const idOf = (name: string): string => vectors.canonical.find((v) => v.name === name)!.sourceId;

describe("source vectors", () => {
  it("every valid vector canonicalizes and hashes as the node does", () => {
    for (const v of vectors.canonical) {
      const s = parseSource(v.input);
      expect(s.canonical, v.name).toBe(v.canonical);
      expect(s.idHex, v.name).toBe(v.sourceId);
      expect(parseCanonicalSource(s.canonical).idHex, v.name).toBe(v.sourceId);
      expect(parseSource(JSON.parse(v.input)).idHex, v.name + " (as an object)").toBe(v.sourceId);
    }
  });

  it("every reject vector is refused with the node's error class", () => {
    for (const v of vectors.reject) {
      const input = v.inputHex !== undefined ? hexToBytes(v.inputHex) : v.input;
      let error: unknown;
      try {
        parseSource(input);
      } catch (e) {
        error = e;
      }
      expect(error, `${v.name}: accepted`).toBeInstanceOf(SourceError);
      expect((error as SourceError).errorClass, `${v.name}: ${(error as Error).message}`).toBe(v.class);
    }
  });

  it("string escaping matches the canonical vectors", () => {
    for (const v of vectors.escaping) expect(canonicalize(v.input), v.input).toBe(v.want);
  });

  it("requires canonical bytes when asked, refuses JS numbers, treats __proto__ as a key", () => {
    expect(() => parseCanonicalSource(vectors.canonical[0]!.input)).toThrow(/canonical form/);
    const doc = JSON.parse(vectors.canonical[0]!.input);
    doc.output.decimals = 8;
    expect(() => parseSource(doc)).toThrow(/numbers are not allowed/);
    expect(canonicalize('{"__proto__": null}')).toBe('{"__proto__":null}');
  });
});

describe("builders", () => {
  it("produce the sources the vectors define", () => {
    const http = defineSource({
      inputs: { px: httpInput({ url: "https://api.example.com/v1/price?symbol=BTC", headers: { accept: "application/json" }, decode: jsonDecode({ price: "$.data.price" }) }) },
      transform: rescale(num(ref("px.price")), { scale: 8 }),
      assert: [gt(ref("$out"), cst(0))],
      output: { type: "int256", decimals: 8 },
      aggregation: { maxDeviationBps: 50, maxAgeMs: 2000 },
    });
    expect(http.idHex).toBe(idOf("http-tolerance"));

    const evm = defineSource({
      inputs: {
        rate: evmCall({
          chain: "eip155:1", to: "0x7f39c581f595b53c5cb19bd0b3f8da6c935e2ca0", sig: "stEthPerToken()", args: [],
          finality: { mode: "finalized", lagMs: 900000 }, decode: abiDecode(["uint256"], { rate: "0" }),
        }),
      },
      transform: ref("rate.rate"),
      output: { type: "int256", decimals: 0 },
    });
    expect(evm.idHex).toBe(idOf("evm-call-sig"));
  });

  it("jsonPriceSource and the lint", async () => {
    const s = jsonPriceSource({ url: "https://a.example/p", path: "$.price", decimals: 8 });
    expect(s.tolerance).toBe(false);
    const pool = defineSource({
      inputs: {
        p: svmAccount({ chain: "solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp", address: "Jito4APyf642JPZPx3hGc6WWJ8zPKtRbRs4P815Awbb", maxAgeMs: 60000, decode: layoutDecode({ a: { offset: 0, type: "u64le" } }) }),
      },
      transform: rescale(ref("p.a"), { scale: 0 }),
      output: { type: "int256", decimals: 0 },
    });
    expect((await lintSource(pool))[0]?.severity).toBe("warning");
    expect((await lintSource(pool, { ownerOf: async () => "whirLbMiicVdio4qvUfM5KAg6Ct8VwpYzGff3uctyCc" }))[0]?.severity).toBe("error");
  });

  it("formatValue and verifyPreimage", () => {
    const word = (hex: string): string => hex.padStart(64, "0");
    expect(formatValue(word("632eac"), { type: "int256", decimals: 2 })).toBe("65000.12");
    expect(formatValue("f".repeat(64), { type: "int256", decimals: 0 })).toBe("-1");
    expect(formatValue("555344" + "00".repeat(29), { type: "string32", decimals: 0 })).toBe("USD");
    const abc = "4e03657aea45a94fc7d47ba826c8d667c0d1e6e33a64a036ec44f58fa12d6c45";
    expect(verifyPreimage(abc, "616263")).toBe(true);
    expect(verifyPreimage(abc, "616264")).toBe(false);
  });

  it("checks chain bounds against the published list", () => {
    const evm = (lag: string) =>
      parseSource(
        `{"v":"1","aggregation":null,"assert":[],"inputs":{"r":{"kind":"evm","chain":"eip155:1","finality":{"mode":"finalized","lagMs":"${lag}","n":null},` +
          `"read":{"method":"balance","address":"0x7f39c581f595b53c5cb19bd0b3f8da6c935e2ca0"},"decode":{"format":"abi","types":["uint256"],"fields":{"v":{"pick":"0"}}}}},` +
          `"transform":{"ref":"r.v"},"output":{"type":"uint256","decimals":"0"}}`,
      );
    checkChains(evm("900000"));
    expect(() => checkChains(evm("60000"))).toThrow(/must be between/);
    expect(() => checkChains(evm("900000"), undefined, () => false)).toThrow(/not supported/);
  });
});
